// extend-surface: a quarter of a 20 × 10 ellipse extruded 10 mm, extended 5 mm past the ellipse's end at (0, 10), keeping its curvature
export function c003(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skEllipticalArc(s1, "e1", { "center" : vector(0, 0) * millimeter, "majorAxis" : vector(1, 0), "majorRadius" : 20 * millimeter, "minorRadius" : 10 * millimeter, "startParameter" : 0, "endParameter" : 0.25 });
    skSolve(s1);
    extrude(context, id + "sheet", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter, "oppositeDirection" : false });
    extendSurface(context, id + "extend1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "sheet", EntityType.BODY), BodyType.SHEET), EntityType.EDGE), vector(0, 10, 5) * millimeter), "endCondition" : ExtendBoundingType.BLIND, "extendDistance" : 5 * millimeter, "oppositeDirection" : false, "maintainCurvature" : true, "tangentPropagation" : false });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "sheet", EntityType.BODY), BodyType.SHEET)), "curves" : curveProbe(context, qBodyType(qCreatedBy(id + "sheet", EntityType.BODY), BodyType.SHEET)) };
}

